impl ConnectionRpcGate {
    pub(crate) fn new() -> Self {
        let accepting = true;
        Self {
            accepting: Mutex::new(accepting),
            tasks: TaskTracker::new(),
        }
    }

    pub(crate) async fn run<F>(&self, future: F)
    where
        F: Future<Output = ()>,
    {
        let token = {
            let accepting = self.accepting.lock().await;
            if !*accepting {
                return;
            }
            self.tasks.token()
        };

        future.await;
        drop(token);
    }

    pub(crate) async fn close(&self) {
        let mut accepting = self.accepting.lock().await;
        *accepting = false;
        self.tasks.close();
    }

    pub(crate) async fn shutdown(&self) {
        self.close().await;
        self.tasks.wait().await;
    }

    #[cfg(test)]

    &self,
    connection_id: ConnectionId,
    session_state: &ConnectionSessionState,
) {
    if timeout(
        CONNECTION_RPC_DRAIN_TIMEOUT,
        session_state.rpc_gate.shutdown(),
    )
    .await
    .is_err()
    {
        tracing::warn!(
            ?connection_id,
            timeout_seconds = CONNECTION_RPC_DRAIN_TIMEOUT.as_secs(),
            "timed out waiting for connection RPCs to drain"
        );
    }
    self.outgoing.connection_closed(connection_id).await;
    self.fs_processor.connection_closed(connection_id).await;
    self.command_exec_processor
        .connection_closed(connection_id)
        .await;
    self.process_exec_processor
        .connection_closed(connection_id)
        .await;
    self.thread_processor.connection_closed(connection_id).await;
}

pub(crate) fn subscribe_running_assistant_turn_count(&self) -> watch::Receiver<usize> {
    self.thread_processor
        .subscribe_running_assistant_turn_count()
}

pub(crate) fn set_listener(
    &mut self,
    cancel_tx: oneshot::Sender<()>,
    conversation: &Arc<CodexThread>,
    watch_registration: WatchRegistration,
    thread_settings_baseline: ThreadSettings,
) -> (mpsc::UnboundedReceiver<ThreadListenerCommand>, u64) {
    if let Some(previous) = self.cancel_tx.replace(cancel_tx) {
        let _ = previous.send(());
    }
    self.listener_generation = self.listener_generation.wrapping_add(1);
    self.last_thread_settings = Some(thread_settings_baseline);
    let (listener_command_tx, listener_command_rx) = mpsc::unbounded_channel();
    self.listener_command_tx = Some(listener_command_tx);
    self.listener_thread = Some(Arc::downgrade(conversation));
    self.watch_registration = watch_registration;
    (listener_command_rx, self.listener_generation)
}

pub(crate) fn clear_listener(&mut self) {
    if let Some(cancel_tx) = self.cancel_tx.take() {
        let _ = cancel_tx.send(());
    }
    self.listener_command_tx = None;
    self.current_turn_history.reset();
    self.listener_thread = None;
    self.watch_registration = WatchRegistration::default();

pub(crate) async fn clear_all_listeners(&self) {
    let thread_states = {
        let state = self.state.lock().await;
        state
            .threads
            .iter()
            .map(|(thread_id, thread_entry)| (*thread_id, thread_entry.state.clone()))
            .collect::<Vec<_>>()
    };

    for (thread_id, thread_state) in thread_states {
        self.unregister_listener_command_tx(thread_id);
        let mut thread_state = thread_state.lock().await;
        tracing::debug!(
            thread_id = %thread_id,
            listener_generation = thread_state.listener_generation,
            had_listener = thread_state.cancel_tx.is_some(),
            had_active_turn = thread_state.active_turn_snapshot().is_some(),
            "clearing thread listener during app-server shutdown"
        );
        thread_state.clear_listener();
    }

let ListenerTaskContext {
    outgoing,
    thread_manager,
    thread_state_manager,
    pending_thread_unloads,
    thread_watch_manager,
    thread_list_state_permit,
    fallback_model_provider,
    codex_home,
    ..
} = listener_task_context;
let outgoing_for_task = Arc::clone(&outgoing);
tokio::spawn(async move {
    loop {
        tokio::select! {
            biased;
            _ = &mut cancel_rx => {
                // Listener was superseded or the thread is being torn down.
                break;
            }
            listener_command = listener_command_rx.recv() => {
                let Some(listener_command) = listener_command else {
                    break;
                };
                handle_thread_listener_command(
                    conversation_id,
                    &conversation,
                    codex_home.as_path(),
                    &thread_state_manager,
                    &thread_state,
                    &thread_watch_manager,
                    &outgoing_for_task,
                    &pending_thread_unloads,
                    listener_command,
                )
                .await;
            }
            event = conversation.next_event() => {
                let event = match event {
                    Ok(event) => event,
                    Err(err) => {
                        tracing::warn!("thread.next_event() failed with: {err}");
                        break;
                    }
                };

                // Track the event before emitting any typed translations
                // so thread-local state such as raw event opt-in stays
                // synchronized with the conversation.
                let raw_events_enabled = {
                    let mut thread_state = thread_state.lock().await;
                    thread_state.track_current_turn_event(&event.id, &event.msg);
                    thread_state.experimental_raw_events
                };
                if matches!(&event.msg, EventMsg::RawResponseItem(_)) && !raw_events_enabled {
                    continue;
                }
                let subscribed_connection_ids = thread_state_manager
                    .subscribed_connection_ids(conversation_id)
                    .await;
                let thread_outgoing = ThreadScopedOutgoingMessageSender::new(
                    outgoing_for_task.clone(),
                    subscribed_connection_ids,
                    conversation_id,
                );

                apply_bespoke_event_handling(
                    event.clone(),
                    conversation_id,
                    conversation.clone(),
                    thread_manager.clone(),
                    thread_outgoing,
                    thread_state.clone(),
                    thread_watch_manager.clone(),
                    thread_list_state_permit.clone(),
                    fallback_model_provider.clone(),
                )
                .await;
            }
            unloading_watchers_open = unloading_state.wait_for_unloading_trigger() => {
                if !unloading_watchers_open {
                    break;
                }
                if !unloading_state.should_unload_now() {
                    continue;
                }
                if matches!(conversation.agent_status().await, AgentStatus::Running) {
                    unloading_state.note_thread_activity_observed();
                    continue;
                }
                {
                    let mut pending_thread_unloads = pending_thread_unloads.lock().await;
                    if pending_thread_unloads.contains(&conversation_id) {
                        continue;
                    }
                    if !unloading_state.should_unload_now() {
                        continue;
                    }
                    pending_thread_unloads.insert(conversation_id);
                }
                unload_thread_without_subscribers(
                    thread_manager.clone(),
                    outgoing_for_task.clone(),
                    pending_thread_unloads.clone(),
                    thread_state_manager.clone(),
                    thread_watch_manager.clone(),
                    conversation_id,
                    conversation.clone(),
                )
                .await;
                break;
            }
        }
    }

    let mut thread_state = thread_state.lock().await;
    if thread_state.listener_generation == listener_generation {
        thread_state_manager.unregister_listener_command_tx(conversation_id);
        thread_state.clear_listener();
    }
});
Ok(())

if pending.emit_thread_goal_update {
    if let Some(state_db) = pending.thread_goal_state_db {
        send_thread_goal_snapshot_notification(outgoing, conversation_id, &state_db).await;
    } else {
        tracing::warn!(
            thread_id = %conversation_id,
            "state db unavailable when reading thread goal for running thread resume"
        );
    }
}
outgoing
    .replay_requests_to_connection_for_thread(connection_id, conversation_id)
    .await;
// App-server owns resume response and snapshot ordering, so wait until
// replay completes before letting extensions react to the idle thread.
if pending.emit_thread_goal_update {
    conversation.emit_thread_idle_lifecycle_if_idle().await;
}
